"""Release steps that follow the GitHub release: the Homebrew formula and the
bonsai-lib crate. Both are idempotent, so a failed run can simply be retried."""

import argparse
import base64
import json
import os
from pathlib import Path
import re
import subprocess
from urllib.error import HTTPError
from urllib.request import Request, urlopen


REPOSITORY_URL = "https://github.com/aymericbeaumet/bonsai"

# The library is published; the CLI is not (`bonsai-cli` on crates.io belongs
# to another project) and installs from GitHub, Homebrew, or mise.
LIBRARY = "bonsai-lib"

# Homebrew platform blocks and the release archive each one installs.
HOMEBREW_ARCHIVES = (
    ("on_macos", (("on_arm", "bonsai-darwin-arm64.tar.gz"), ("on_intel", "bonsai-darwin-amd64.tar.gz"))),
    ("on_linux", (("on_arm", "bonsai-linux-arm64.tar.gz"), ("on_intel", "bonsai-linux-amd64.tar.gz"))),
)

FORMULA = """\
# frozen_string_literal: true

# Generated by bonsai's release workflow; do not edit.
class Bonsai < Formula
  desc "Git worktrees without the bookkeeping"
  homepage "{homepage}"
  version "{version}"
  license "MIT"

{platforms}
  def install
    bin.install "bonsai"
    generate_completions_from_executable(bin/"bonsai", "completions")
  end

  def caveats
    <<~EOS
      To let bonsai change your shell's directory, add this to your shell's
      startup file:
        eval "$(bonsai init zsh)"     # ~/.zshrc
        eval "$(bonsai init bash)"    # ~/.bashrc
        bonsai init fish | source     # ~/.config/fish/config.fish
    EOS
  end

  test do
    assert_match "bonsai #{{version}}", shell_output("#{{bin}}/bonsai --version")
  end
end
"""


def api(method, path, data=None, allow_missing=False):
    url = path if path.startswith("https://") else "https://api.github.com" + path
    payload = json.dumps(data).encode() if data is not None else None
    request = Request(url, data=payload, method=method, headers={
        "Authorization": "Bearer " + os.environ.get("GH_TOKEN", ""),
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Content-Type": "application/json",
    })
    try:
        with urlopen(request, timeout=120) as response:
            body = response.read()
            return json.loads(body) if body else None
    except HTTPError as error:
        if allow_missing and error.code == 404:
            return None
        raise


def require(variable, purpose):
    if not os.environ.get(variable):
        raise SystemExit(f"{variable} is required to {purpose}")


def release_checksums(tag):
    url = f"{REPOSITORY_URL}/releases/download/{tag}/SHA256SUMS"
    with urlopen(url, timeout=120) as response:
        return parse_checksums(response.read().decode())


def parse_checksums(text):
    checksums = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        digest, name = line.split()
        checksums[name.lstrip("*")] = digest
    return checksums


def homebrew_formula(tag, checksums):
    platforms = []
    for os_block, arches in HOMEBREW_ARCHIVES:
        lines = [f"  {os_block} do\n"]
        for arch_block, archive in arches:
            if archive not in checksums:
                raise ValueError(f"{tag} has no {archive} in SHA256SUMS")
            lines.append(
                f"    {arch_block} do\n"
                f'      url "{REPOSITORY_URL}/releases/download/{tag}/{archive}"\n'
                f'      sha256 "{checksums[archive]}"\n'
                "    end\n"
            )
        lines.append("  end\n")
        platforms.append("".join(lines))
    return FORMULA.format(
        homepage=REPOSITORY_URL,
        version=tag.removeprefix("v"),
        platforms="\n".join(platforms),
    )


def update_homebrew(tag, tap):
    require("GH_TOKEN", f"update the {tap} formula (set the HOMEBREW_TAP_TOKEN secret)")
    formula = homebrew_formula(tag, release_checksums(tag))
    path = f"/repos/{tap}/contents/Formula/bonsai.rb"
    current = api("GET", path, allow_missing=True)
    if current is not None and base64.b64decode(current["content"]).decode() == formula:
        print(f"{tap} already installs {tag}")
        return
    body = {
        "message": f"chore: update bonsai to {tag.removeprefix('v')}",
        "content": base64.b64encode(formula.encode()).decode(),
    }
    if current is not None:
        body["sha"] = current["sha"]
    api("PUT", path, body)
    print(f"{tap} now installs {tag}")


def crate_published(name, version):
    request = Request(f"https://crates.io/api/v1/crates/{name}/{version}", headers={
        "User-Agent": f"bonsai-release ({REPOSITORY_URL})",
    })
    try:
        with urlopen(request, timeout=60) as response:
            published = json.load(response)["version"]
    except HTTPError as error:
        if error.code == 404:
            return False
        raise
    if published["crate"] != name or published["num"] != version:
        raise ValueError(f"Unexpected crates.io response for {name} {version}")
    if published.get("repository") != REPOSITORY_URL:
        raise ValueError(f"{name} {version} is already published by another repository")
    return True


def stamp(version, root=Path(".")):
    """Write the release version into both manifests and the CLI's library
    requirement; the committed version is a placeholder."""
    if not re.fullmatch(r"\d+\.\d+\.\d+", version):
        raise ValueError(f"Releases need a major.minor.patch version, not {version!r}")
    for manifest in (root / "Cargo.toml", root / LIBRARY / "Cargo.toml"):
        text = manifest.read_text()
        text, count = re.subn(r'(?m)^version = "[^"]*"', f'version = "{version}"', text, count=1)
        if count != 1:
            raise ValueError(f"{manifest} has no package version")
        manifest.write_text(text)
    cli = root / "Cargo.toml"
    text, count = re.subn(
        rf'(package = "{LIBRARY}", path = "{LIBRARY}", version = ")[^"]*"',
        rf'\g<1>{version}"',
        cli.read_text(),
    )
    if count != 1:
        raise ValueError(f"Cargo.toml does not require {LIBRARY} by path and version")
    cli.write_text(text)


def publish_crate(version, run=subprocess.run):
    if crate_published(LIBRARY, version):
        print(f"{LIBRARY} {version} is already on crates.io")
        return
    require("CARGO_REGISTRY_TOKEN", f"publish {LIBRARY} {version}")
    stamp(version)
    run(["cargo", "update", "--workspace"], check=True)
    # The stamped manifests are the only changes, so the tree is dirty.
    run(["cargo", "publish", "--locked", "--allow-dirty", "--package", LIBRARY], check=True)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    homebrew = commands.add_parser("homebrew", help="update the Homebrew formula")
    homebrew.add_argument("--tag", required=True)
    homebrew.add_argument("--tap", required=True)
    crate = commands.add_parser("crate", help=f"publish {LIBRARY} to crates.io")
    crate.add_argument("--version", required=True)
    args = parser.parse_args()
    if args.command == "homebrew":
        update_homebrew(args.tag, args.tap)
    else:
        publish_crate(args.version)
